/**
 * Ownership-handover offers, and the one multi-table write that completes one.
 *
 * An offer is *open* while its row is `pending` and `expires_at` is still in
 * the future. A lapsed row is left exactly as it is until the next offer
 * replaces it, so acting on a lapsed offer changes nothing. Every write that
 * resolves an offer is conditional on it still being open, and the writes
 * that span several rows run in one transaction: two racing calls can never
 * both win, and a handover is never half-applied.
 */
import { and, eq, gt, isNull, lte, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toMember, toOrganization, toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Member, Role } from "@/types/member";
import type {
  Organization,
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** One role change applied while completing a handover. */
export interface HandoverRoleChange {
  readonly member: Member;
  readonly from: Role;
  readonly to: Role;
}

/** Everything `completeHandover` changed, for the service to announce. */
export interface CompletedHandover {
  readonly handover: OwnershipHandover;
  readonly organization: Organization;
  /** In the order they were applied: the promotion, then the demotion. */
  readonly roleChanges: readonly HandoverRoleChange[];
}

function pendingPredicate(orgId: OrgId) {
  return and(
    orgPredicate(ownershipHandovers.orgId, orgId),
    eq(ownershipHandovers.status, "pending"),
  );
}

function openPredicate(orgId: OrgId, at: IsoTimestamp) {
  return and(pendingPredicate(orgId), gt(ownershipHandovers.expiresAt, at));
}

/**
 * The org's unresolved offer, whether or not it has lapsed — callers compare
 * `expiresAt` themselves when the difference matters to them.
 */
export async function findUnresolvedHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(pendingPredicate(orgId))
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/** The offer that can still be acted on at `at`, or `null`. */
export async function findOpenHandover(
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(openPredicate(orgId, at))
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Opens an offer, or returns `null` when one is already open. A lapsed offer
 * is retired as `expired` in the same transaction, which is what frees the
 * org's single `pending` slot.
 */
export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
  expiresAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  return getDb().transaction((tx) => {
    tx.update(ownershipHandovers)
      .set({ status: "expired" })
      .where(
        and(
          pendingPredicate(orgId),
          lte(ownershipHandovers.expiresAt, createdAt),
        ),
      )
      .run();

    const open = tx
      .select({ id: ownershipHandovers.id })
      .from(ownershipHandovers)
      .where(pendingPredicate(orgId))
      .get();
    if (open) return null;

    const row = tx
      .insert(ownershipHandovers)
      .values({
        id: newId(),
        orgId,
        fromUserId,
        toUserId,
        status: "pending",
        expiresAt,
        createdAt,
        resolvedAt: null,
      })
      .returning()
      .get();

    return toOwnershipHandover(row);
  });
}

/**
 * Closes an open offer as declined or canceled. Returns `null` when the offer
 * is no longer open at `at` — resolved by someone else, or lapsed.
 */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Extract<OwnershipHandoverStatus, "declined" | "canceled">,
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at })
    .where(and(openPredicate(orgId, at), eq(ownershipHandovers.id, handoverId)))
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Withdraws the open offer when `userId` is either side of it. Called when a
 * member leaves the org; returns the withdrawn offer, or `null` if none was.
 */
export async function cancelOpenHandoverInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at })
    .where(
      and(
        openPredicate(orgId, at),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Completes an open offer atomically: marks it accepted, gives the offered
 * member the owner role, records them as the org's owner and steps the
 * previous owner down to admin if they still hold the owner role.
 *
 * The promotion is written before the demotion, so there is no point at which
 * the org has no owner. Returns `null` — having changed nothing — when the
 * offer is no longer open at `at`.
 */
export async function completeHandover(
  orgId: OrgId,
  handoverId: string,
  at: IsoTimestamp,
): Promise<CompletedHandover | null> {
  return getDb().transaction((tx) => {
    const accepted = tx
      .update(ownershipHandovers)
      .set({ status: "accepted", resolvedAt: at })
      .where(
        and(openPredicate(orgId, at), eq(ownershipHandovers.id, handoverId)),
      )
      .returning()
      .get();
    if (!accepted) return null;

    const liveMember = (userId: string) =>
      tx
        .select()
        .from(members)
        .where(
          and(
            orgPredicate(members.orgId, orgId),
            eq(members.userId, userId),
            isNull(members.archivedAt),
          ),
        )
        .get();

    const setRole = (memberId: string, role: Role) => {
      const row = tx
        .update(members)
        .set({ role, updatedAt: at })
        .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
        .returning()
        .get();
      if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
      return toMember(row);
    };

    const incoming = liveMember(accepted.toUserId);
    if (!incoming || incoming.status !== "active") {
      // Throwing rolls the acceptance back: an offer can only be completed
      // by someone who is still an active member.
      throw new Error(
        `User ${accepted.toUserId} is not an active member of org ${orgId}`,
      );
    }

    const roleChanges: HandoverRoleChange[] = [];

    if (incoming.role !== "owner") {
      roleChanges.push({
        member: setRole(incoming.id, "owner"),
        from: incoming.role,
        to: "owner",
      });
    }

    const organization = tx
      .update(organizations)
      .set({ ownerId: accepted.toUserId, updatedAt: at })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
    if (!organization) throw new Error(`Organization ${orgId} not found`);

    const outgoing = liveMember(accepted.fromUserId);
    if (outgoing && outgoing.id !== incoming.id && outgoing.role === "owner") {
      roleChanges.push({
        member: setRole(outgoing.id, "admin"),
        from: "owner",
        to: "admin",
      });
    }

    return {
      handover: toOwnershipHandover(accepted),
      organization: toOrganization(organization),
      roleChanges,
    };
  });
}
EOF

