open(p,'a').write('''
/**
 * Offers the workspace to another active member. Only the *recorded* owner
 * (`Organization.ownerId`) may do this — holding the owner role is not enough
 * — and only one offer can be open at a time. The offered member, and nobody
 * else, is notified.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (target === null || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const createdAt = toIsoTimestamp(new Date());
  const handover = await handoverRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    createdAt,
    addDays(createdAt, OWNERSHIP_HANDOVER_TTL_DAYS),
  );
  if (handover === null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You have been offered ownership of a workspace",
    body: `Accept to become the owner of ${org.name}. The offer lapses on ${handover.expiresAt}`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over, whatever role they hold. They
 * become the recorded owner with the owner role, and the previous owner steps
 * down to admin if they still held the owner role.
 *
 * The role changes deliberately bypass `updateMemberRole`: the accepting
 * member need not be able to manage roles, and the repository promotes before
 * it demotes, so the last-owner invariant holds throughout without being
 * asked. Each change is still announced as `member.role_changed`.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const at = toIsoTimestamp(new Date());
  const offer = await requireOfferFor(actor, orgId, at);

  const completed = await handoverRepo.completeHandover(orgId, offer.id, at);
  if (completed === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  for (const change of completed.roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.member.id,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: completed.handover.fromUserId,
    toUserId: completed.handover.toUserId,
  });

  return completed.organization;
}

/** The offered member turns the offer down; the owner may then offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const at = toIsoTimestamp(new Date());
  const offer = await requireOfferFor(actor, orgId, at);

  const declined = await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    at,
  );
  if (declined === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return declined;
}

/**
 * The owner withdraws their open offer. With nothing open there is nothing to
 * withdraw, whoever asks; with an offer open, only the recorded owner may.
 */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const at = toIsoTimestamp(new Date());
  const offer = await handoverRepo.findOpenHandover(orgId, at);
  if (offer === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  const canceled = await handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "canceled",
    at,
  );
  if (canceled === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return canceled;
}

/** The open offer, visible to every member of the workspace; `null` if none. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return handoverRepo.findOpenHandover(orgId, toIsoTimestamp(new Date()));
}

/**
 * Recorded ownership is a fact about one user, not a role rank, so the matrix
 * cannot decide it: a second member holding the owner role is still refused.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;

  throw new PermissionDeniedError("org:transfer_ownership", {
    allowed: false,
    action: "org:transfer_ownership",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/**
 * The offer `actor` may accept or decline at `at`. Anyone but the offered
 * member is told nothing is pending; the offered member learns when theirs
 * has lapsed. A lapsed offer is only read here, never altered.
 */
async function requireOfferFor(
  actor: Actor,
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const offer = await handoverRepo.findUnresolvedHandover(orgId);
  if (offer === null || offer.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (offer.expiresAt <= at) {
    throw new OwnershipHandoverError("expired");
  }
  return offer;
}
''')

