cd "$PWD" && cat > tests/services/ownership-handover.test.ts <<'EOF'
/**
 * Ownership handover: offer, accept, decline, withdraw, lapse and the guards.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError, isDomainError, toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function fresh(tenant: Tenant, userId: UserId): Promise<Actor> {
  const actor = await memberService.resolveActor(userId, tenant.org.id);
  if (!actor) throw new Error("no actor");
  return actor;
}

function refusal(reason: string) {
  return expect.objectContaining({ name: "OwnershipHandoverError", reason, code: "conflict" });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("ownership handover", () => {
  it("offers to a member, notifies only them and shows the offer to everyone", async () => {
    const t = await createTenant("ho-offer");
    const offer = await orgService.initiateOwnershipHandover(
      t.actors.owner,
      t.org.id,
      t.userIds.member,
    );

    expect(offer).toMatchObject({
      orgId: t.org.id,
      fromUserId: t.userIds.owner,
      toUserId: t.userIds.member,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(7 * DAY_MS);

    for (const role of ["member", "admin", "viewer", "owner"] as const) {
      const page = await listNotifications(t.actors.owner, {
        orgId: t.org.id,
        recipientId: t.userIds[role],
        unreadOnly: false,
        kind: ["ownership_handover"],
        limit: 25,
        cursor: null,
      });
      expect(page.items, role).toHaveLength(role === "member" ? 1 : 0);
    }

    await expect(
      orgService.getPendingOwnershipHandover(t.actors.viewer, t.org.id),
    ).resolves.toEqual(offer);

    await expect(
      orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin),
    ).rejects.toEqual(refusal("pending_exists"));
  });

  it("transfers ownership on acceptance and announces it", async () => {
    const t = await createTenant("ho-accept");
    const off = activityService.registerActivityListeners();
    detachers.push(off);

    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);

    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");
    const ownerCounts: number[] = [];
    detachers.push(
      subscribe("member.role_changed", async () => {
        const owners = await memberRepo.listMembers({
          orgId: t.org.id,
          role: "owner",
          limit: 25,
          cursor: null,
        });
        ownerCounts.push(owners.items.length);
      }),
    );

    const org = await orgService.acceptOwnershipHandover(t.actors.viewer, t.org.id);
    expect(org.ownerId).toBe(t.userIds.viewer);

    const newOwner = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    const oldOwner = await memberRepo.findMember(t.org.id, t.userIds.owner);
    expect(newOwner?.role).toBe("owner");
    expect(oldOwner?.role).toBe("admin");

    expect(roleChanges).toHaveLength(2);
    expect(roleChanges[0]).toMatchObject({
      orgId: t.org.id,
      actorId: t.userIds.viewer,
      memberId: newOwner?.id,
      from: "viewer",
      to: "owner",
    });
    expect(roleChanges[1]).toMatchObject({
      actorId: t.userIds.viewer,
      memberId: oldOwner?.id,
      from: "owner",
      to: "admin",
    });
    expect(ownerCounts.every((n) => n >= 1)).toBe(true);
    expect(transfers).toEqual([
      expect.objectContaining({
        orgId: t.org.id,
        actorId: t.userIds.viewer,
        fromUserId: t.userIds.owner,
        toUserId: t.userIds.viewer,
      }),
    ]);

