    ).rejects.toEqual(refusal("nothing_pending"));
    await expect(
      orgService.cancelOwnershipHandover(t.actors.owner, t.org.id),
    ).rejects.toEqual(refusal("nothing_pending"));

    const org = await orgRepo.findOrgById(t.org.id);
    expect(org?.ownerId).toBe(t.userIds.owner);
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))?.role).toBe("member");

    // A lapsed offer does not block a new one.
    const again = await orgService.initiateOwnershipHandover(
      t.actors.owner,
      t.org.id,
      t.userIds.admin,
    );
    expect(again.status).toBe("pending");
    await expect(
      orgService.acceptOwnershipHandover(t.actors.member, t.org.id),
    ).rejects.toEqual(refusal("nothing_pending"));
    const accepted = await orgService.acceptOwnershipHandover(t.actors.admin, t.org.id);
    expect(accepted.ownerId).toBe(t.userIds.admin);
  });

  it("validates the target and the tenant", async () => {
    const t = await createTenant("ho-guards");
    const other = await createTenant("ho-guards-other");

    await expect(
      orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner),
    ).rejects.toEqual(refusal("self"));
    await expect(
      orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, "nobody" as UserId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      orgService.initiateOwnershipHandover(t.actors.admin, t.org.id, t.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await orgService.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    await expect(
      orgService.getPendingOwnershipHandover(other.actors.owner, other.org.id),
    ).resolves.toBeNull();

    for (const call of [
      () => orgService.initiateOwnershipHandover(other.actors.owner, t.org.id, t.userIds.member),
      () => orgService.acceptOwnershipHandover(other.actors.owner, t.org.id),
      () => orgService.declineOwnershipHandover(other.actors.owner, t.org.id),
      () => orgService.cancelOwnershipHandover(other.actors.owner, t.org.id),
      () => orgService.getPendingOwnershipHandover(other.actors.owner, t.org.id),
    ]) {
      await expect(call()).rejects.toBeInstanceOf(TenantScopeError);
    }
  });

  it("maps the refusal to a conflict", () => {
    const error = new OwnershipHandoverError("pending_exists");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("conflict");
    expect(error.reason).toBe("pending_exists");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error).code).toBe("conflict");
  });
});
EOF
